+      padding: 1rem;
+      border: 1px solid var(--border);
+      border-radius: 1rem;
+      background: var(--bg-field);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 0.75rem;
+    }
+
+    input[type="checkbox"] {
+      width: 1.1rem;
+      height: 1.1rem;
+      margin-top: 0.2rem;
+      accent-color: var(--accent);
+      flex: 0 0 auto;
+    }
+
+    label {
+      display: block;
+      font-weight: 600;
+      cursor: pointer;
+    }
+
+    .required {
+      color: var(--accent-strong);
+    }
+
+    .helper-text {
+      margin: 0.35rem 0 0;
+      color: var(--muted);
+      font-size: 0.95rem;
