+      border-radius: 999px;
+      padding: 0.85rem 1.2rem;
+      font: inherit;
+      font-weight: 700;
+      color: var(--text);
+      background: linear-gradient(180deg, #5873d8 0%, #4158b8 100%);
+      cursor: pointer;
+      transition: transform 0.15s ease, box-shadow 0.15s ease;
+    }
+
+    button:hover {
+      box-shadow: 0 10px 24px #091126;
+    }
+
+    button:active {
+      transform: translateY(1px);
+    }
+
+    :is(a, button, input):focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 0;
+      color: var(--success);
+      font-weight: 600;
+    }
+
